insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_39_v1'
from (values
('127.232.d.4',3,'A boutique owner tracks sales in a spreadsheet, takes online orders, and uses social media to show new arrivals. These are:','["advanced technology applications", "hand sewing tools", "fabric swatches", "garment racks"]'::jsonb,0,'Software and online tools support modern retail.','original'),
('127.232.d.4',4,'A store uses a point-of-sale system that updates inventory every time an item is sold. This technology mainly helps with:','["hemming", "accurate stock tracking", "pattern cutting", "fabric dyeing"]'::jsonb,1,'POS systems keep inventory counts current.','original'),
('127.232.d.5',3,'Knowing the difference between knit and woven fabrics helps a fashion retailer:','["avoid customers", "lower the thread count", "describe and sell products accurately", "stop selling"]'::jsonb,2,'Fashion knowledge supports accurate selling.','original'),
('127.232.d.5',4,'A salesperson explains that a cotton-polyester blend resists wrinkles better than pure cotton. This shows knowledge of:','["store lighting", "tax law", "shipping routes", "textile properties"]'::jsonb,3,'Fiber content affects performance.','original'),
('127.232.d.6',3,'A stock room worker keeps boxes off the walkway and stacks them safely. This is applying:','["safety regulations", "fashion trends", "display rules", "pricing rules"]'::jsonb,0,'Safe storage prevents falls and injuries.','original'),
('127.232.d.6',4,'A customer spills a drink near the fitting rooms. Which action best applies safety practices?','["Tell the customer to clean it", "Place a wet-floor sign and clean it up", "Wait until closing", "Step over it"]'::jsonb,1,'Marking and cleaning prevents slips.','original'),
('127.232.d.9',3,'A retail employee learns to fold stock quickly and neatly, which saves time. This builds technical skills for:','["waste", "delay", "efficiency", "clutter"]'::jsonb,2,'Skilled routines speed up work.','original'),
('127.232.d.9',4,'Which habit improves efficiency when restocking a clothing store?','["Putting items back at random", "Stacking everything in one pile", "Leaving boxes on the floor", "Sorting items by size and style before placing them"]'::jsonb,3,'Pre-sorting saves time on the floor.','original'),
('127.232.d.1.A',3,'A sales associate writes a clear product description and proofreads her email to a vendor. She is applying:','["English language arts skills", "gym skills", "welding skills", "music skills"]'::jsonb,0,'Writing skills support business communication.','original'),
('127.232.d.1.A',4,'Which task uses English language arts skills in a fashion store?','["Steaming a garment", "Writing an accurate product tag and ad copy", "Hanging a display", "Counting the register"]'::jsonb,1,'Descriptive writing requires correct language.','original'),
('127.232.d.1 B',3,'A shirt costs $24.50 and a scarf costs $13.25. What is the total before tax?','["$38.25", "$36.75", "$37.75", "$37.25"]'::jsonb,2,'24.50 + 13.25 = 37.75.','original'),
('127.232.d.1 B',4,'A $60 jacket is 25% off. What is the sale price?','["$35", "$15", "$50", "$45"]'::jsonb,3,'60 x 0.75 = 45.','original'),
('127.232.d.2.A',3,'A salesperson talks to a teenager in casual language and to a business client in more formal language. She is adapting:','["language for audience and situation", "her shoes", "her store hours", "her price tags"]'::jsonb,0,'Language should fit the listener.','original'),
('127.232.d.2.A',4,'Which message best fits a formal email to a fashion supplier?','["hey whats up lol", "Dear Mr. Patel, I would like to confirm our order for the fall line.", "need clothes asap", "yo send the stuff"]'::jsonb,1,'Formal tone fits business partners.','original'),
('127.232.d.2.B',3,'A manager puts today''s tasks in order of priority and tells the team. She is:','["hiding tasks", "guessing", "organizing oral and written information", "erasing tasks"]'::jsonb,2,'Organized information helps teams work.','original'),
('127.232.d.2.B',4,'Which opening-day checklist is best organized?','["One sentence", "A blank sheet", "A random list", "Tasks grouped by area with a person assigned to each"]'::jsonb,3,'Grouping and assigning makes tasks clear.','original'),
('127.232.d.2.C',3,'A buyer notices which colors sold best last month and tells her team. She is:','["interpreting and communicating data", "guessing", "ignoring results", "hiding information"]'::jsonb,0,'Reporting sales data guides decisions.','original'),
('127.232.d.2.C',4,'Which statement communicates sales data clearly?','["Things moved.", "Blue sweaters sold 40 units in June compared with 15 in May.", "Some items were fine.", "Blue sold well, I think."]'::jsonb,1,'Specific numbers support decisions.','original'),
('127.232.d.2.D',3,'A student shows her classmates a fall fashion line using slides. This is a:','["password", "private diary", "formal presentation", "receipt"]'::jsonb,2,'A planned talk with slides is formal.','original'),
('127.232.d.2.D',4,'Explaining a new display idea to a coworker while folding sweaters is:','["a formal keynote", "a shareholder report", "a legal filing", "an informal presentation"]'::jsonb,3,'Casual sharing is informal.','original'),
('127.232.d.2.E',3,'A shopper describes the exact style she wants. The associate nods, takes notes, and repeats it back. This is:','["active listening", "daydreaming", "interrupting", "ignoring"]'::jsonb,0,'Repeating confirms understanding.','original'),
('127.232.d.2.E',4,'A customer asks for something ''trendy but comfortable.'' The best response is to:','["show everything", "ask what styles or fabrics she has liked before", "guess", "end the talk"]'::jsonb,1,'Questions clarify vague requests.','original'),
('127.232.d.2.F',3,'A store serves shoppers of many ages and cultures. A good associate will:','["use stereotypes", "avoid some customers", "communicate respectfully with each person", "rush people"]'::jsonb,2,'Respect builds loyalty.','original'),
('127.232.d.2.F',4,'A customer who is hard of hearing visits the store. Which approach is helpful?','["Walk away", "Ignore the customer", "Speak louder from far away", "Face the customer, speak clearly, and offer written details"]'::jsonb,3,'Clear, patient communication helps.','original'),
('127.232.d.2.G',3,'A store replies politely to a social media complaint and offers to fix the problem. This builds:','["customer relations", "delay", "tension", "mistrust"]'::jsonb,0,'Good PR protects the brand.','original'),
('127.232.d.2.G',4,'Thanking employees and keeping customers informed about sales builds both internal and external:','["delays", "public relations", "errors", "clutter"]'::jsonb,1,'PR strengthens relationships.','original'),
('127.232.d.3.A',3,'A manager reviews return reasons to find why one dress style keeps coming back. This is:','["guessing", "ignoring data", "critical thinking with data", "luck"]'::jsonb,2,'Analyzing data helps solve problems.','original'),
('127.232.d.3.A',4,'A store''s sales dropped after moving the display. Critical thinking suggests she should:','["stop selling", "restore it without checking", "blame the weather", "compare sales before and after and test other causes"]'::jsonb,3,'Compare data before concluding.','original'),
('127.232.d.3.B',3,'Three employees disagree about how to lay out a sale rack. A good approach is to:','["discuss ideas and decide together", "flip a coin", "let one dictate", "avoid the topic"]'::jsonb,0,'Group problem solving uses communication.','original'),
('127.232.d.3.B',4,'Which phrase helps a team solve a staffing problem?','["That''s your fault.", "What options do we have to cover the schedule?", "Not my job.", "I won''t help."]'::jsonb,1,'Solution-focused language helps.','original'),
('127.232.d.7.A',3,'A store lead sets the sales goal, assigns jobs, and cheers on the team. She is showing:','["avoidance", "laziness", "leadership", "carelessness"]'::jsonb,2,'Leaders guide groups toward goals.','original'),
('127.232.d.7.A',4,'A busy holiday weekend approaches. A good leader will:','["cut hours for everyone", "ignore the rush", "wait and see", "plan schedules and tasks ahead of time"]'::jsonb,3,'Planning supports collective goals.','original'),
('127.232.d.7.B',3,'A manager thanks a stock clerk for staying late and gives helpful feedback. This promotes:','["effective working relationships", "tension", "distance", "resentment"]'::jsonb,0,'Appreciation builds trust.','original'),
('127.232.d.7.B',4,'Which is constructive feedback to a new sales associate?','["You''re bad at this.", "Your greeting is friendly; try asking one more question before suggesting items.", "Never mind.", "Do better."]'::jsonb,1,'Specific, supportive feedback helps.','original'),
('127.232.d.7.C',3,'A student organization opens its meeting by having the president call the group to order. This follows:','["a secret rule", "a price list", "parliamentary procedure", "a menu"]'::jsonb,2,'Parliamentary procedure organizes meetings.','original'),
('127.232.d.7.C',4,'In parliamentary procedure, a member who wants the group to consider an idea makes a:','["guess", "complaint", "rumor", "motion"]'::jsonb,3,'A motion brings business before the group.','original'),
('127.232.d.7.D',3,'An experienced buyer shows a new employee how to read a sales report. This is:','["mentoring", "copying", "competing", "hiding information"]'::jsonb,0,'Mentors teach and inspire.','original'),
('127.232.d.7.D',4,'A good mentor in fashion retail:','["corrects harshly", "shares knowledge patiently and encourages questions", "keeps tricks secret", "avoids teaching"]'::jsonb,1,'Patience builds skill.','original'),
('127.232.d.8.A',3,'A salesperson returns extra change a customer was given by mistake. This is:','["carelessness", "gossip", "ethical conduct", "greed"]'::jsonb,2,'Honesty is ethical.','original'),
('127.232.d.8.A',4,'A coworker offers to give you credit for a sale you did not make. The ethical choice is to:','["say nothing", "accept the credit", "ask for a bonus", "decline and give credit to the person who made it"]'::jsonb,3,'Honesty includes crediting work correctly.','original'),
('127.232.d.8.B',3,'A retailer wants to print a famous brand''s logo on its own shirts without permission. This could violate:','["copyright and trademark law", "traffic law", "tax rules", "safety rules"]'::jsonb,0,'Logos are protected intellectual property.','original'),
('127.232.d.8.B',4,'A designer uses a pattern created by another artist on her tote bags without a license. This is:','["fair use", "a copyright violation", "public domain use", "ethical practice"]'::jsonb,1,'Using protected art without permission infringes copyright.','original'),
('127.232.d.10.A',3,'Selecting styles to purchase, ordering, receiving, and pricing merchandise describes the process of:','["dyeing", "sewing", "retail buying", "window cleaning"]'::jsonb,2,'Retail buying brings merchandise into stores.','original'),
('127.232.d.10.A',4,'Which step comes first in the retail buying process?','["Mark down leftover stock", "Send thank-you cards", "Close the register", "Determine customer needs and set a buying budget"]'::jsonb,3,'Planning precedes purchasing.','original'),
('127.232.d.10.B',3,'Trade shows, showrooms, and market centers are:','["wholesale market resources", "coat racks", "retail checkouts", "fitting rooms"]'::jsonb,0,'Buyers find wholesale products there.','original'),
('127.232.d.10.B',4,'A buyer wants to see many vendors'' new lines in one place. A good resource is:','["a fashion blog only", "a trade show", "a clearance rack", "a mailing label"]'::jsonb,1,'Trade shows gather many vendors.','original'),
('127.232.d.10.C',3,'Comparing a luxury market with a discount market is comparing:','["jewelry designs only", "fabrics only", "apparel markets", "hair styles"]'::jsonb,2,'Markets differ by price level and customers.','original'),
('127.232.d.10.C',4,'A fast-fashion market differs from a couture market mainly in:','["store hours", "the number of buttons", "the color of tags", "speed of production and price level"]'::jsonb,3,'Fast fashion is quick and affordable; couture is custom and costly.','original'),
('127.232.d.10.D',3,'A store sells winter coats at full price in October and marks them down in January. This shows how timing affects:','["pricing", "sewing", "dyeing", "hanging"]'::jsonb,0,'Seasonal demand changes price.','original'),
('127.232.d.10.D',4,'Why do retailers discount swimwear in late summer?','["Swimwear is harder to make", "Demand falls as the season ends", "Stores run out of tags", "Customers prefer paying more"]'::jsonb,1,'End-of-season demand drops.','original'),
('127.232.d.10.E',3,'A store pays $20 for a shirt and sells it for $45. What is the markup amount?','["$45", "$20", "$25", "$65"]'::jsonb,2,'45 - 20 = 25.','original'),
('127.232.d.10.E',4,'A scarf costs $12 wholesale and the retailer adds a 100% markup on cost. What is the retail price?','["$20", "$12", "$36", "$24"]'::jsonb,3,'100% of 12 is 12; 12 + 12 = 24.','original'),
('127.232.d.10.F',3,'A department store, a boutique, and an online shop are different types of:','["retail outlets", "stitches", "fabrics", "patterns"]'::jsonb,0,'Retail outlets sell to consumers in different ways.','original'),
('127.232.d.10.F',4,'Which outlet usually offers the widest range of merchandise under one roof?','["A street vendor", "A department store", "A pop-up kiosk", "A single-brand boutique"]'::jsonb,1,'Department stores carry many categories.','original'),
('127.232.d.10.G',3,'Sourcing garments from factories in other countries is called:','["window dressing", "local weaving", "offshore sourcing", "hand tailoring"]'::jsonb,2,'Offshore sourcing buys overseas.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_39_v1'
from (values
('127.232.d.10.G',4,'One reason retailers use offshore sourcing is to:','["avoid all trade rules", "raise the price of fabric", "increase shipping time to zero", "lower production costs"]'::jsonb,3,'Lower labor costs can reduce prices.','original'),
('127.232.d.10.H',3,'A buyer plans how many items to order, what to charge, and how many to sell by month. She is composing a:','["scenario plan", "window display", "press release", "fitting schedule"]'::jsonb,0,'Scenario plans project sales and inventory.','original'),
('127.232.d.10.H',4,'If expected sales drop in a scenario plan, the buyer should:','["ignore the plan", "reduce purchases or adjust pricing", "order more stock", "close the store"]'::jsonb,1,'Plans guide purchase adjustments.','original'),
('127.232.d.11.A',3,'The idea that a business should meet customers'' needs and wants in order to be successful is the:','["shipping concept", "tax concept", "marketing concept", "tailoring concept"]'::jsonb,2,'Marketing focuses on customer needs.','original'),
('127.232.d.11.A',4,'A store surveys shoppers before choosing which jeans to carry. This applies the marketing concept by:','["copying a competitor exactly", "ignoring customers", "choosing the cheapest", "putting customer needs first"]'::jsonb,3,'Customer needs guide decisions.','original'),
('127.232.d.11.B',3,'Pricing, selling, promoting, and distributing fashion goods are:','["marketing functions", "cutting steps", "sewing steps", "dyeing steps"]'::jsonb,0,'Marketing includes several functions.','original'),
('127.232.d.11.B',4,'Setting the price of a new line of sneakers is the marketing function of:','["distribution", "pricing", "storage", "financing"]'::jsonb,1,'Pricing decides what customers pay.','original'),
('127.232.d.11.C',3,'Product, price, place, and promotion are the four parts of the:','["supply chain", "retail plan", "marketing mix", "sewing kit"]'::jsonb,2,'The marketing mix combines these elements.','original'),
('127.232.d.11.C',4,'Selling a new line only in high-end boutiques is a decision about:','["price", "promotion", "product", "place"]'::jsonb,3,'Place covers where goods are sold.','original'),
('127.232.d.11.D',3,'A brand that makes athletic wear for runners has identified a:','["target market", "fabric type", "store layout", "tax rate"]'::jsonb,0,'A target market is the group a business aims to serve.','original'),
('127.232.d.11.D',4,'Why is knowing the target market important?','["It lowers taxes", "It helps match products, prices, and promotions to buyers", "It removes competition", "It shortens store hours"]'::jsonb,1,'Targeting improves marketing results.','original'),
('127.232.d.11.E',3,'Aiming a product at one specific group is called market segmentation. Aiming at everyone is:','["segmenting", "niche selling", "mass marketing", "targeting"]'::jsonb,2,'Mass marketing treats all customers alike.','original'),
('127.232.d.11.E',4,'An advantage of market segmentation is that it:','["removes all risk", "reaches everyone equally", "costs nothing", "allows messages tailored to a group''s needs"]'::jsonb,3,'Tailoring improves response.','original'),
('127.232.d.11.F',3,'Researching what colors are trending and how shoppers use social media is studying:','["trends and emerging technologies", "shoe sizes", "store keys", "tax forms"]'::jsonb,0,'Trend research guides fashion marketing.','original'),
('127.232.d.11.F',4,'A retailer starts using augmented reality so shoppers can see clothes on themselves virtually. This is an:','["manual process", "emerging technology", "old method", "sewing step"]'::jsonb,1,'AR is a new technology for retail.','original'),
('127.232.d.11.G',3,'A shop that sells only plus-size vintage dresses is practicing:','["mass marketing", "random selling", "niche marketing", "discount selling"]'::jsonb,2,'A niche focuses on a small specialized market.','original'),
('127.232.d.11.G',4,'Which is an example of a niche market in fashion?','["All clothing for all ages", "A general discount store", "Any store with many items", "Adaptive clothing for people with disabilities"]'::jsonb,3,'Adaptive clothing serves a specialized group.','original'),
('127.232.d.11.H',3,'Religious holidays, regional customs, and school dress codes are:','["cultural and societal influences on fashion", "tax rules", "sewing tools", "store rules only"]'::jsonb,0,'Culture shapes what people wear.','original'),
('127.232.d.11.H',4,'A retailer expecting a cultural festival might stock:','["unrelated items only", "traditional garments customers wear for the event", "nothing new", "only winter coats"]'::jsonb,1,'Understanding culture helps stock the right goods.','original'),
('127.232.d.11.I',3,'Selling a U.S. fashion brand to customers in other countries is:','["private marketing", "garage sales", "international marketing", "local marketing only"]'::jsonb,2,'International marketing reaches global buyers.','original'),
('127.232.d.11.I',4,'International marketing has affected the fashion industry by:','["ending all trends", "closing all stores", "stopping trade", "spreading trends and creating global brands"]'::jsonb,3,'Global exposure spreads styles.','original'),
('127.232.d.12.A',3,'Advertising, visual merchandising, publicity, and personal selling are the parts of the:','["promotional mix", "store plan", "pricing chart", "fabric chart"]'::jsonb,0,'The promotional mix combines promotion tools.','original'),
('127.232.d.12.A',4,'A store window display is part of which promotional tool?','["Publicity only", "Visual merchandising", "Personal selling", "Direct mail only"]'::jsonb,1,'Displays attract attention visually.','original'),
('127.232.d.12.B',3,'Arranging a mannequin outfit with accessories to attract shoppers is:','["dyeing", "shipping", "visual merchandising", "tailoring"]'::jsonb,2,'Visual merchandising presents products.','original'),
('127.232.d.12.B',4,'Placing the best-selling items at eye level near the entrance is a visual merchandising technique that:','["hides products", "confuses customers", "slows customers", "draws attention to key products"]'::jsonb,3,'Placement guides attention.','original'),
('127.232.d.12.C',3,'A store compares sales before and after a campaign to see if it worked. This is analyzing the plan''s:','["effectiveness", "color", "packaging", "fabric"]'::jsonb,0,'Results show whether a plan succeeded.','original'),
('127.232.d.12.C',4,'Which measure would show a promotion''s effectiveness?','["The number of tags printed", "Change in sales during the promotion", "The number of mannequins", "The color of the banner"]'::jsonb,1,'Sales change shows impact.','original'),
('127.232.d.12.D',3,'Advertising a ''half-price'' sale when the price was first raised is:','["a courtesy", "honest advertising", "a deceptive practice", "fair pricing"]'::jsonb,2,'Misleading discounts deceive customers.','original'),
('127.232.d.12.D',4,'Claiming a coat is ''genuine leather'' when it is plastic is:','["fair advertising", "accurate labeling", "good service", "false advertising"]'::jsonb,3,'Misrepresenting materials is deceptive.','original'),
('127.232.d.12.E',3,'A store tells the truth about its sale and discount terms. This is:','["ethical promotion", "cheating", "hiding", "deception"]'::jsonb,0,'Honest ads are ethical.','original'),
('127.232.d.12.E',4,'Which advertisement is ethical?','["One that exaggerates features", "One that shows real prices and accurate product details", "One that uses fake testimonials", "One that hides fees"]'::jsonb,1,'Ethical promotion is truthful.','original'),
('127.232.d.13.A',3,'Sales, coupons, loyalty programs, and special events are types of:','["sewing methods", "tax rules", "business promotion strategies", "tailoring tools"]'::jsonb,2,'These strategies encourage purchases.','original'),
('127.232.d.13.A',4,'A loyalty program that gives points for each purchase encourages:','["returns", "theft", "closing", "repeat customers"]'::jsonb,3,'Rewards bring shoppers back.','original'),
('127.232.d.13.B',3,'A shopper who buys the latest style to look current is motivated by:','["fashion and social acceptance", "tax savings", "no reason", "a coupon only"]'::jsonb,0,'Buying motives include status and image.','original'),
('127.232.d.13.B',4,'A parent buys durable school clothes because they last, showing a motive of:','["boredom", "value and durability", "curiosity", "status"]'::jsonb,1,'Practical buyers look for value.','original'),
('127.232.d.13.C',3,'A press release announcing a store''s grand opening is part of:','["bookkeeping", "shipping", "public relations and publicity", "cutting fabric"]'::jsonb,2,'Publicity earns free media attention.','original'),
('127.232.d.13.C',4,'Publicity differs from paid advertising because it is usually:','["always paid for", "illegal", "private", "not paid for by the business"]'::jsonb,3,'Publicity is earned media.','original'),
('127.232.d.13.D',3,'A boutique runs a trunk show to preview new styles to preferred customers. This is a:','["promotional activity", "recall", "tax form", "return policy"]'::jsonb,0,'Special events promote products.','original'),
('127.232.d.13.D',4,'Why might a retailer host a charity fashion event?','["To lose money", "To promote the brand while supporting a cause", "To raise taxes", "To avoid customers"]'::jsonb,1,'Events build goodwill.','original'),
('127.232.d.13.E',3,'Choosing the date, venue, budget, and models for a fashion show is:','["hanging a sign", "dyeing fabric", "planning a special event", "sewing a gown"]'::jsonb,2,'Event planning organizes all details.','original'),
('127.232.d.13.E',4,'Which should be decided first when planning a retail fashion show?','["The song title", "The model''s shoes", "The color of the napkins", "The goal and the budget"]'::jsonb,3,'Goals and budgets guide planning.','original'),
('127.232.d.13.F',3,'A show called ''Summer Under the Stars'' with matching decor, music, and clothing has a:','["theme", "receipt", "hang tag", "budget"]'::jsonb,0,'A theme unifies the show.','original'),
('127.232.d.13.F',4,'A good fashion show theme should:','["distract from the clothes", "tie the clothing, music, and decor together", "confuse the audience", "ignore the products"]'::jsonb,1,'Consistency makes the show effective.','original'),
('127.232.d.13.G',3,'A scale drawing of the runway and seating helps planners:','["avoid planning", "print tags", "visualize the staging before building it", "train models"]'::jsonb,2,'Scale drawings show how space is used.','original'),
('127.232.d.13.G',4,'On a scale of 1 inch = 4 feet, a 20-foot runway is drawn as:','["10 inches", "4 inches", "20 inches", "5 inches"]'::jsonb,3,'20 / 4 = 5.','original'),
('127.232.d.13.H',3,'Assigning someone to dress models, someone to run the music, and someone to greet guests is describing:','["fashion show responsibilities", "store hours", "shipping dates", "tax duties"]'::jsonb,0,'Roles keep the show running.','original'),
('127.232.d.13.H',4,'The person who coordinates when models enter and exit the runway is the:','["cashier", "backstage manager", "stylist assistant", "accountant"]'::jsonb,1,'The backstage manager controls timing.','original'),
('127.232.d.13.I',3,'A short announcement sent to newspapers about a store''s upcoming sale is a:','["price tag", "pattern", "press release", "tax return"]'::jsonb,2,'Press releases publicize events.','original'),
('127.232.d.13.I',4,'Which information belongs at the top of a press release?','["A list of prices", "A long story about the founder", "Unrelated jokes", "The key news: what, who, when, and where"]'::jsonb,3,'Lead with the essentials.','original'),
('127.232.d.14.A',3,'Mannequins, props, signs, and lighting are components used in developing:','["displays", "hems", "patterns", "orders"]'::jsonb,0,'Displays use many components.','original'),
('127.232.d.14.A',4,'Which item is a component of a window display?','["A cash register", "A mannequin dressed in the featured outfit", "A delivery truck", "A shipping label"]'::jsonb,1,'Mannequins show products.','original'),
('127.232.d.14.B',3,'Using repeated shapes and a clear focal point in a display applies design elements and:','["taxes", "mistakes", "principles", "labels"]'::jsonb,2,'Elements and principles guide design.','original'),
('127.232.d.14.B',4,'Placing the largest, brightest item in the center to attract the eye creates:','["noise", "confusion", "clutter", "emphasis"]'::jsonb,3,'Emphasis directs attention.','original'),
('127.232.d.14.C',3,'Window displays face outside shoppers while islands and shelves inside the store are:','["interior displays", "exterior displays", "private displays", "hidden displays"]'::jsonb,0,'Displays can be interior or exterior.','original'),
('127.232.d.14.C',4,'An exterior display is mainly used to:','["show tax rates", "attract passersby into the store", "list store policies", "hide products"]'::jsonb,1,'Exterior displays draw traffic.','original')
